// postgresqlQueries answers every query in Querier against postgresql.
type postgresqlQueries struct {
	archiveReport                      string
	createReport                       string
	deleteReportsByReporter            string
	getReport                          string
	getReportCreatedAt                 string
	listReports                        string
	listReportsByReporter              string
	listReportsByReporterDescending    string
	listReportsByStatus                string
	listReportsByStatusDescending      string
	listReportsBySubjectType           string
	listReportsBySubjectTypeDescending string
	listReportsDescending              string
	listReportsForSubject              string
	listReportsForSubjectDescending    string
	transitionReport                   string
	updateReport                       string
}

// newPostgreSQL returns the postgresql querier with prefix substituted into every
// table name the analyzer identified.
func newPostgreSQL(prefix string) *postgresqlQueries {
	return &postgresqlQueries{
		archiveReport:                      strings.ReplaceAll(archiveReportPostgreSQL, prefixMarker, prefix),
		createReport:                       strings.ReplaceAll(createReportPostgreSQL, prefixMarker, prefix),
		deleteReportsByReporter:            strings.ReplaceAll(deleteReportsByReporterPostgreSQL, prefixMarker, prefix),
		getReport:                          strings.ReplaceAll(getReportPostgreSQL, prefixMarker, prefix),
		getReportCreatedAt:                 strings.ReplaceAll(getReportCreatedAtPostgreSQL, prefixMarker, prefix),
		listReports:                        strings.ReplaceAll(listReportsPostgreSQL, prefixMarker, prefix),
		listReportsByReporter:              strings.ReplaceAll(listReportsByReporterPostgreSQL, prefixMarker, prefix),
		listReportsByReporterDescending:    strings.ReplaceAll(listReportsByReporterDescendingPostgreSQL, prefixMarker, prefix),
		listReportsByStatus:                strings.ReplaceAll(listReportsByStatusPostgreSQL, prefixMarker, prefix),
		listReportsByStatusDescending:      strings.ReplaceAll(listReportsByStatusDescendingPostgreSQL, prefixMarker, prefix),
		listReportsBySubjectType:           strings.ReplaceAll(listReportsBySubjectTypePostgreSQL, prefixMarker, prefix),
		listReportsBySubjectTypeDescending: strings.ReplaceAll(listReportsBySubjectTypeDescendingPostgreSQL, prefixMarker, prefix),
		listReportsDescending:              strings.ReplaceAll(listReportsDescendingPostgreSQL, prefixMarker, prefix),
		listReportsForSubject:              strings.ReplaceAll(listReportsForSubjectPostgreSQL, prefixMarker, prefix),
		listReportsForSubjectDescending:    strings.ReplaceAll(listReportsForSubjectDescendingPostgreSQL, prefixMarker, prefix),
		transitionReport:                   strings.ReplaceAll(transitionReportPostgreSQL, prefixMarker, prefix),
		updateReport:                       strings.ReplaceAll(updateReportPostgreSQL, prefixMarker, prefix),
	}
}

// ArchiveReport runs the :execrows query against postgresql.
func (q *postgresqlQueries) ArchiveReport(ctx context.Context, db DBTX, arg ArchiveReportParams) (int64, error) {
	result, err := db.ExecContext(ctx, q.archiveReport,
		arg.ID,
		arg.Scope,
	)
	if err != nil {
		return 0, err
	}

	return result.RowsAffected()
}

// CreateReport runs the :exec query against postgresql.
func (q *postgresqlQueries) CreateReport(ctx context.Context, db DBTX, arg CreateReportParams) error {
	_, err := db.ExecContext(ctx, q.createReport,
		arg.ID,
		arg.Scope,
		arg.Reporter,
		arg.Kind,
		arg.Details,
		arg.SubjectType,
		arg.SubjectID,
		arg.Status,
		arg.Resolution,
		arg.ClosedAt,
	)

	return err
}

// DeleteReportsByReporter runs the :execrows query against postgresql.
func (q *postgresqlQueries) DeleteReportsByReporter(ctx context.Context, db DBTX, arg DeleteReportsByReporterParams) (int64, error) {
	result, err := db.ExecContext(ctx, q.deleteReportsByReporter,
		arg.Scope,
		arg.Reporter,
	)
	if err != nil {
		return 0, err
	}

	return result.RowsAffected()
}

// GetReport runs the :one query against postgresql.
func (q *postgresqlQueries) GetReport(ctx context.Context, db DBTX, arg GetReportParams) (GetReportRow, error) {
	row := db.QueryRowContext(ctx, q.getReport,
		arg.ID,
		arg.Scope,
	)

	var i GetReportRow

	err := row.Scan(
		&i.ID,
		&i.Scope,
		&i.Reporter,
		&i.Kind,
		&i.Details,
		&i.SubjectType,
		&i.SubjectID,
		&i.Status,
		&i.Resolution,
		&i.ClosedAt,
		&i.CreatedAt,
		&i.LastUpdatedAt,
		&i.ArchivedAt,
	)

	return i, err
}

// GetReportCreatedAt runs the :one query against postgresql.
func (q *postgresqlQueries) GetReportCreatedAt(ctx context.Context, db DBTX, arg GetReportCreatedAtParams) (GetReportCreatedAtRow, error) {
	row := db.QueryRowContext(ctx, q.getReportCreatedAt,
		arg.ID,
		arg.Scope,
	)

	var i GetReportCreatedAtRow

	err := row.Scan(
		&i.CreatedAt,
	)

	return i, err
}

// ListReports runs the :many query against postgresql.
func (q *postgresqlQueries) ListReports(ctx context.Context, db DBTX, arg ListReportsParams) ([]ListReportsRow, error) {
	rows, err := db.QueryContext(ctx, q.listReports,
		arg.CreatedAfter,
		arg.CreatedBefore,
		arg.UpdatedAfter,
		arg.UpdatedBefore,
		arg.IncludeArchived,
		arg.Scope,
		arg.PageCursor,
		arg.ResultLimit,
	)
	if err != nil {
		return nil, err
	}

	defer func() { _ = rows.Close() }()

	var items []ListReportsRow

	for rows.Next() {
		var i ListReportsRow

		if err := rows.Scan(
			&i.ID,
			&i.Scope,
			&i.Reporter,
			&i.Kind,
			&i.Details,
			&i.SubjectType,
			&i.SubjectID,
			&i.Status,
			&i.Resolution,
			&i.ClosedAt,
			&i.CreatedAt,
			&i.LastUpdatedAt,
			&i.ArchivedAt,
			&i.FilteredCount,
			&i.TotalCount,
		); err != nil {
			return nil, err
		}

		items = append(items, i)
	}

	if err := rows.Err(); err != nil {
		return nil, err
	}

	return items, nil
}

